}

function toInt(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n < 1) return undefined;
  return Math.floor(n);
}

function stripEmoji(emoji) {
  return emoji.replace(/^:+|:+$/g, '');
}

const USAGE = `Slack Web API helper

Usage:
  node slack_api.cjs <command> [arguments...] [options]

Token fallback order: --token <token> | --token-file <file> | $SLACK_BOT_TOKEN | $SLACK_TOKEN

Commands:
  auth-test                                    Verify the token (auth.test)
  post <channel> <text...>                     Send a message (chat.postMessage)
       [--thread-ts TS] [--blocks JSON|@file]
  reply <channel> <thread-ts> <text...>        Reply inside a thread
  update <channel> <ts> <text...>              Edit a message (chat.update)
  delete <channel> <ts>                        Delete a message (chat.delete)
  history <channel> [--limit N] [--cursor C]   Read history (conversations.history)
       [--oldest TS] [--latest TS]
  replies <channel> <ts> [--limit N] [--cursor C]
                                               Read thread replies (conversations.replies)
  channels [--types T] [--limit N] [--cursor C] [--include-archived]
                                               List channels (conversations.list)
  channel-info <channel>                       Channel details (conversations.info)
  channel-create <name> [--private]            Create a channel (conversations.create)
  channel-join <channel>                       Join a channel (conversations.join)
  channel-leave <channel>                      Leave a channel (conversations.leave)
  channel-set-topic <channel> <topic...>       Set a channel topic (conversations.setTopic)
  users [--limit N] [--cursor C]               List users (users.list)
  user-info <user>                             User details (users.info)
  user-by-email <email>                        Find a user by email (users.lookupByEmail)
  search <query...> [--count N]                Search messages (search.messages)
  react <channel> <emoji> <ts>                 Add a reaction (reactions.add)
  unreact <channel> <emoji> <ts>               Remove a reaction (reactions.remove)
  api <method> <json...|@file>                 Call any Web API method directly

Channels accept an ID (C..., D..., G...) or a name (#name). Message timestamps
(ts) are Slack identifiers like 1699999999.000100 and are always kept as strings.
`;

async function main() {
  const argv = process.argv.slice(2);
  if (argv.length === 0 || argv[0] === 'help' || argv[0] === '--help' || argv[0] === '-h') {
    process.stdout.write(USAGE);
    return;
  }

  const cmd = argv[0];
  const { positionals: pos, opts } = parseArgs(argv.slice(1));
  const token = resolveToken(opts);
  if (!token) {
    throw new Error(
      'No Slack token found. Set SLACK_BOT_TOKEN or SLACK_TOKEN, or pass --token <token> / --token-file <path>.',
    );
  }

  let method = null;
  let payload = null;

  switch (cmd) {
    case 'auth-test': {
      method = 'auth.test';
      payload = {};
      break;
    }
    case 'post': {
      if (pos.length < 1) throw new Error('post requires: <channel> <text...>');
      const channel = await resolveChannel(token, pos[0], opts);
      const text = pos.slice(1).join(' ').trim();
      payload = { channel };
      if (opts['thread-ts']) payload.thread_ts = opts['thread-ts'];
      if (opts.blocks) payload.blocks = parseBlocks(opts.blocks);
      if (text) payload.text = text;
      if (!payload.text && !payload.blocks) throw new Error('post needs text or --blocks');
      method = 'chat.postMessage';
      break;
    }
    case 'reply': {
      if (pos.length < 2) throw new Error('reply requires: <channel> <thread-ts> <text...>');
      const channel = await resolveChannel(token, pos[0], opts);
      const text = pos.slice(2).join(' ').trim();
      if (!text && !opts.blocks) throw new Error('reply needs text or --blocks');
      payload = { channel, thread_ts: pos[1] };
      if (opts.blocks) payload.blocks = parseBlocks(opts.blocks);
      if (text) payload.text = text;
      method = 'chat.postMessage';
      break;
    }
    case 'update': {
      if (pos.length < 2) throw new Error('update requires: <channel> <ts> <text...>');
      const channel = await resolveChannel(token, pos[0], opts);
      const text = pos.slice(2).join(' ').trim();
      if (!text && !opts.blocks) throw new Error('update needs text or --blocks');
      payload = { channel, ts: pos[1] };
      if (opts.blocks) payload.blocks = parseBlocks(opts.blocks);
      if (text) payload.text = text;
      method = 'chat.update';
      break;
    }
    case 'delete': {
      if (pos.length < 2) throw new Error('delete requires: <channel> <ts>');
      const channel = await resolveChannel(token, pos[0], opts);
      payload = { channel, ts: pos[1] };
      method = 'chat.delete';
      break;
    }
    case 'history': {
      if (pos.length < 1) throw new Error('history requires: <channel>');
      const channel = await resolveChannel(token, pos[0], opts);
      payload = { channel };
      const limit = toInt(opts.limit);
      if (limit) payload.limit = limit;
      if (opts.cursor) payload.cursor = opts.cursor;
      if (opts.oldest) payload.oldest = opts.oldest;
      if (opts.latest) payload.latest = opts.latest;
      if (opts.inclusive) payload.inclusive = true;
      method = 'conversations.history';
      break;
    }
    case 'replies': {
      if (pos.length < 2) throw new Error('replies requires: <channel> <ts>');
      const channel = await resolveChannel(token, pos[0], opts);
      payload = { channel, ts: pos[1] };
      const limit = toInt(opts.limit);
      if (limit) payload.limit = limit;
      if (opts.cursor) payload.cursor = opts.cursor;
      method = 'conversations.replies';
      break;
    }
    case 'channels': {
      payload = { types: opts.types || 'public_channel', exclude_archived: !opts['include-archived'] };
      const limit = toInt(opts.limit);
      if (limit) payload.limit = limit;
      if (opts.cursor) payload.cursor = opts.cursor;
      method = 'conversations.list';
      break;
    }
    case 'channel-info': {
      if (pos.length < 1) throw new Error('channel-info requires: <channel>');
      const channel = await resolveChannel(token, pos[0], opts);
      payload = { channel };
      method = 'conversations.info';
      break;
    }
    case 'channel-create': {
      if (pos.length < 1) throw new Error('channel-create requires: <name>');
      payload = { name: pos[0], is_private: !!opts.private };
      if (opts['team-id']) payload.team_id = opts['team-id'];
      method = 'conversations.create';
      break;
    }
    case 'channel-join': {
      if (pos.length < 1) throw new Error('channel-join requires: <channel>');
      const channel = await resolveChannel(token, pos[0], opts);
      payload = { channel };
      method = 'conversations.join';
      break;
    }
    case 'channel-leave': {
      if (pos.length < 1) throw new Error('channel-leave requires: <channel>');
      const channel = await resolveChannel(token, pos[0], opts);
      payload = { channel };
      method = 'conversations.leave';
      break;
    }
    case 'channel-set-topic': {
      if (pos.length < 2) throw new Error('channel-set-topic requires: <channel> <topic...>');
      const channel = await resolveChannel(token, pos[0], opts);
      payload = { channel, topic: pos.slice(1).join(' ').trim() };
      method = 'conversations.setTopic';
      break;
    }
    case 'users': {
      payload = {};
      const limit = toInt(opts.limit);
      if (limit) payload.limit = limit;
      if (opts.cursor) payload.cursor = opts.cursor;
      method = 'users.list';
      break;
    }
    case 'user-info': {
      if (pos.length < 1) throw new Error('user-info requires: <user>');
      payload = { user: pos[0] };
      method = 'users.info';
      break;
    }
    case 'user-by-email': {
      if (pos.length < 1) throw new Error('user-by-email requires: <email>');
      payload = { email: pos[0] };
      method = 'users.lookupByEmail';
      break;
    }
    case 'search': {
      const query = pos.join(' ').trim();
      if (!query) throw new Error('search requires: <query...>');
      payload = { query };
      const count = toInt(opts.count || opts.limit);
      if (count) payload.count = count;
      method = 'search.messages';
      break;
    }
    case 'react':
    case 'unreact': {
      if (pos.length < 3) throw new Error(`${cmd} requires: <channel> <emoji> <ts>`);
      const channel = await resolveChannel(token, pos[0], opts);
      const name = stripEmoji(pos[1]);
      if (!name) throw new Error(`Invalid emoji: "${pos[1]}"`);
      payload = { channel, name, timestamp: pos[2] };
      method = cmd === 'react' ? 'reactions.add' : 'reactions.remove';
      break;
    }
    case 'api': {
      if (pos.length < 1) throw new Error('api requires: <method> [<json-body...>|@file]');
      method = pos[0];
      if (!/^[a-z][a-z0-9._-]*$/i.test(method)) throw new Error(`Invalid Slack method name: "${method}"`);
      if (pos.length === 1) {
        payload = {};
      } else if (pos[1].startsWith('@')) {
        payload = JSON.parse(fs.readFileSync(path.resolve(pos[1].slice(1)), 'utf8'));
      } else {
        payload = JSON.parse(pos.slice(1).join(' '));
      }
      break;
    }
    default: {
      throw new Error(`Unknown command "${cmd}". Run "node slack_api.cjs help" for usage.`);
    }
  }

  const json = await callApi(method, payload, token, opts);
  process.stdout.write(`Success: ${method}\n`);
  process.stdout.write(`${JSON.stringify(json, null, 2)}\n`);
  const nextCursor = json.response_metadata && json.response_metadata.next_cursor;
  if (nextCursor) {
    process.stdout.write(`NOTE: more results available; pass --cursor ${nextCursor} to fetch the next page.\n`);
  }
}

main().catch((err) => {
  const label = err instanceof SlackApiError ? `Slack API error (${err.method})` : 'Failure';
  process.stderr.write(`${label}: ${err.message}\n`);
  if (err instanceof SlackApiError && err.raw && process.argv.includes('--verbose')) {
    process.stderr.write(`Response: ${JSON.stringify(err.raw)}\n`);
  }
  process.exitCode = 1;
});
